"use server";

import { importActorFromSpotlightHtml } from "@/lib/actorImport";
import { redirect } from "next/navigation";
import { supabaseServer } from "@/lib/supabaseServer";

export async function importFromSpotlightUrl(formData: FormData) {
  const url = (formData.get("spotlight_url") as string)?.trim();
  if (!url) {
    throw new Error("Spotlight URL is required");
  }

  const response = await fetch(url);
  if (!response.ok) {
    console.error("Failed to fetch Spotlight URL:", url, response.status);
    throw new Error("Could not fetch Spotlight page");
  }

  const html = await response.text();

  await importActorFromSpotlightHtml(html);

  redirect("/admin/actors?import=success");
}

// Scaffold for PDF upload: store in Supabase for now.
// Parsing of PDF to be added later.
export async function uploadSpotlightPdf(formData: FormData) {
  const file = formData.get("spotlight_pdf") as File | null;
  if (!file) {
    throw new Error("No file uploaded");
  }

  const supabase = supabaseServer();

  const arrayBuffer = await file.arrayBuffer();
  const fileBytes = new Uint8Array(arrayBuffer);

  const fileName = `spotlight-cvs/${Date.now()}-${file.name}`;

  const { error } = await supabase.storage.from("documents").upload(fileName, fileBytes, {
    contentType: file.type || "application/pdf",
  });

  if (error) {
    console.error("Error uploading Spotlight CV PDF:", error);
    throw new Error("Failed to upload Spotlight CV");
  }

  // For now, just redirect with a notice.
  // Later we will hook in PDF parsing + extraction.
  redirect("/admin/actors?pdf_uploaded=1");
}

